import Foundation

// Where the relay gets its bytes from. Stage 1 plugs in a source that reads the real link in ranged windows; the MKV→MP4 remux plugs in
// another one. The server, the parser and the session registry do not know the difference.

/// What a source says about one file it serves.
public struct RelayResource: Equatable, Sendable {
    public var contentType: String
    /// Total size in bytes, or nil when it is not known up front (the body then ends when the connection closes and Range is ignored).
    public var length: Int64?
    public var acceptsRanges: Bool

    public init(contentType: String, length: Int64?, acceptsRanges: Bool) {
        self.contentType = contentType
        self.length = length
        self.acceptsRanges = acceptsRanges
    }
}

/// A body being read, one chunk at a time. The server asks for the next chunk only after the previous one was handed to the network, so
/// a slow receiver slows the reading instead of filling memory.
public protocol RelayBodyReader: AnyObject, Sendable {
    /// The next chunk, or nil at the end of the body.
    func next() async throws -> Data?
    /// Stops the reading and releases whatever it holds. Safe to call more than once.
    func cancel()
}

public protocol RelaySource: AnyObject, Sendable {
    /// Facts about a file. Throws `RelayError.notFound` for any name the source does not serve.
    func resource(named leaf: String) async throws -> RelayResource
    /// Opens the file for reading. `range` is nil for the whole file, otherwise exactly those bytes (the server has already checked it
    /// against `resource.length`). Failures that happen before the first byte are thrown here, so the server can still answer with a
    /// real error status.
    func open(_ leaf: String, range: ClosedRange<Int64>?) async throws -> RelayBodyReader
    /// Releases everything the source holds (network sessions, files). Called when the session ends.
    func close()
}

/// A source made of generated bytes, for tests: byte `i` of the file is `i % 251`, which has no short period that a wrong offset could
/// hide behind. Counts what was produced, opened and cancelled, and can be told to fail.
public final class MemoryRelaySource: RelaySource, @unchecked Sendable {
    public let leaf: String
    public let contentType: String
    public let size: Int64
    public let reportsLength: Bool
    public let acceptsRanges: Bool
    public let chunkSize: Int

    /// Throw this from `open`.
    public var failOpen: RelayError?
    /// Fail the reader with `RelayError.upstreamUnreachable(code: -1005)` once this many bytes of one body were produced.
    public var failAfterBytes: Int64?

    private let lock = NSLock()
    private var _produced: Int64 = 0
    private var _openedRanges: [ClosedRange<Int64>?] = []
    private var _cancels = 0
    private var _closed = false

    public init(leaf: String = "video.mkv", contentType: String = "video/x-matroska", size: Int64, reportsLength: Bool = true,
                acceptsRanges: Bool = true, chunkSize: Int = 64 * 1024) {
        self.leaf = leaf
        self.contentType = contentType
        self.size = size
        self.reportsLength = reportsLength
        self.acceptsRanges = acceptsRanges
        self.chunkSize = chunkSize
    }

    public static func byte(at offset: Int64) -> UInt8 {
        return UInt8(truncatingIfNeeded: offset % 251)
    }

    /// The bytes the source produces for `range`, for comparing against what came out of the server.
    public static func expected(_ range: ClosedRange<Int64>) -> Data {
        var data = Data(capacity: Int(range.count))
        var offset = range.lowerBound
        while offset <= range.upperBound {
            data.append(byte(at: offset))
            offset += 1
        }
        return data
    }

    public var producedBytes: Int64 { return locked { _produced } }
    public var openedRanges: [ClosedRange<Int64>?] { return locked { _openedRanges } }
    public var openCount: Int { return locked { _openedRanges.count } }
    public var cancelCount: Int { return locked { _cancels } }
    public var isClosed: Bool { return locked { _closed } }

    private func locked<T>(_ body: () -> T) -> T {
        lock.lock()
        defer { lock.unlock() }
        return body()
    }

    fileprivate func record(produced count: Int64) {
        locked { _produced += count }
    }

    fileprivate func recordCancel() {
        locked { _cancels += 1 }
    }

    public func resource(named leaf: String) async throws -> RelayResource {
        guard leaf == self.leaf else { throw RelayError.notFound }
        return RelayResource(contentType: contentType, length: reportsLength ? size : nil, acceptsRanges: acceptsRanges)
    }

    public func open(_ leaf: String, range: ClosedRange<Int64>?) async throws -> RelayBodyReader {
        guard leaf == self.leaf else { throw RelayError.notFound }
        locked { _openedRanges.append(range) }
        if let failure = failOpen { throw failure }
        // An empty file has `last == -1`, so its reader ends at once.
        return MemoryBodyReader(source: self, next: range?.lowerBound ?? 0, last: range?.upperBound ?? (size - 1), failAfter: failAfterBytes)
    }

    public func close() {
        locked { _closed = true }
    }
}

private final class MemoryBodyReader: RelayBodyReader, @unchecked Sendable {
    private let source: MemoryRelaySource
    private let lock = NSLock()
    private var position: Int64
    private let last: Int64
    private let failAfter: Int64?
    private var served: Int64 = 0
    private var cancelled = false

    init(source: MemoryRelaySource, next: Int64, last: Int64, failAfter: Int64?) {
        self.source = source
        self.position = next
        self.last = last
        self.failAfter = failAfter
    }

    func next() async throws -> Data? {
        return try nextChunk()
    }

    private func nextChunk() throws -> Data? {
        lock.lock()
        defer { lock.unlock() }
        if cancelled || position > last { return nil }
        if let limit = failAfter, served >= limit { throw RelayError.upstreamUnreachable(code: -1005) }
        var count = Int64(source.chunkSize)
        count = min(count, last - position + 1)
        if let limit = failAfter { count = min(count, limit - served) }
        let chunk = MemoryRelaySource.expected(position...(position + count - 1))
        position += count
        served += count
        source.record(produced: count)
        return chunk
    }

    func cancel() {
        lock.lock()
        let first = !cancelled
        cancelled = true
        lock.unlock()
        if first { source.recordCancel() }
    }
}
